        <Link
          href="/"
          className="flex items-center gap-2 px-4 py-2 bg-black/60 hover:bg-black/80 border border-white/15 rounded-full text-xs font-bold text-zinc-300 hover:text-white transition-all backdrop-blur-md"
        >
