              <p className="text-[11px] text-zinc-400">
                You can use your own key or use the built-in CortexCode quota. Free keys available at{' '}
                <a href="https://aistudio.google.com" target="_blank" rel="noopener noreferrer" className="text-purple-400 underline">
                  aistudio.google.com
                </a>
              </p>
            </div>
            <div className="flex items-center gap-2 w-full md:w-auto">
              <select
                value={apiProvider}
                onChange={e => setApiProvider(e.target.value as 'gemini' | 'openai')}
