                );
              })}
            </div>
          )}

        </div>

        {/* Bottom User Profile & Settings Drawer Trigger */}
        <div className="p-3 border-t border-white/10 bg-black/50 shrink-0">
          <div className="flex items-center justify-between gap-2">
            <button
              onClick={onOpenSettings}
              className={`flex items-center gap-3 p-2 rounded-xl hover:bg-white/10 transition-all text-left group min-w-0 ${
                isCollapsed ? 'justify-center w-full' : 'flex-1'
              }`}
            >
              <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-purple-600 to-pink-600 flex items-center justify-center font-bold text-xs text-white shadow-md shrink-0">
                {userName.charAt(0)}
              </div>
              {!isCollapsed && (
                <div className="min-w-0 flex-1">
                  <div className="text-xs font-bold text-white truncate">{userName}</div>
                  <div className="text-[10px] text-purple-400 font-semibold truncate">{userEmail}</div>
                </div>
              )}
            </button>

            {!isCollapsed && (
              <div className="flex items-center gap-1">
                <button
                  onClick={onOpenSettings}
                  className="p-2 text-zinc-400 hover:text-white hover:bg-white/10 rounded-xl transition-colors"
                  title="Settings"
                >
                  <Settings size={16} />
                </button>
                <button
                  onClick={onLogout}
                  className="p-2 text-red-400 hover:text-red-300 hover:bg-red-950/40 rounded-xl transition-colors"
                  title="Sign Out"
                >
                  <LogOut size={16} />
                </button>
              </div>
            )}
          </div>
        </div>

      </aside>
    </>
  );
}

'use client';

import React, { useEffect } from 'react';
import { Mic, MicOff, Square, X, Volume2 } from 'lucide-react';
import { useSpeechRecognition } from '@/hooks/useSpeechRecognition';
import { useToast } from '@/providers/ToastProvider';

interface VoiceInputProps {
  onTranscript: (text: string) => void;
}

export default function VoiceInput({ onTranscript }: VoiceInputProps) {
  const toast = useToast();
  const { isSupported, state, transcript, interimTranscript, error, start, stop, cancel, reset } =
    useSpeechRecognition();

  // When final transcript arrives, push it to composer
  useEffect(() => {
    if (transcript && state === 'idle') {
      onTranscript(transcript);
      reset();
    }
  }, [transcript, state, onTranscript, reset]);

  // Show error toast
  useEffect(() => {
    if (error) {
      toast.showError?.('Voice Input Error', error) ??
        toast.showInfo('Voice Input', error);
    }
  }, [error, toast]);

  if (!isSupported) {
    return (
      <button
        type="button"
        disabled
        title="Voice input is not supported in this browser"
        className="p-2.5 text-zinc-600 rounded-2xl cursor-not-allowed"
      >
        <MicOff size={18} />
      </button>
    );
  }

  if (state === 'listening') {
    return (
      <div className="flex items-center gap-1.5">
        {/* Animated listening indicator */}
        <div className="flex items-center gap-1 px-2 py-1 bg-red-950/50 border border-red-500/40 rounded-xl">
          <div className="relative flex">
            <span className="w-2 h-2 rounded-full bg-red-500 animate-ping absolute" />
            <span className="w-2 h-2 rounded-full bg-red-400 relative" />
          </div>
          <span className="text-[10px] font-bold text-red-300 ml-1">Listening...</span>
        </div>

        {/* Stop recording */}
        <button
          type="button"
          onClick={stop}
          title="Stop recording"
          className="p-2 bg-red-600 hover:bg-red-500 text-white rounded-xl transition-all shadow-md"
        >
          <Square size={14} className="fill-white" />
        </button>

        {/* Cancel */}
        <button
          type="button"
          onClick={cancel}
          title="Cancel"
          className="p-2 text-zinc-400 hover:text-white hover:bg-white/10 rounded-xl transition-colors"
        >
          <X size={14} />
        </button>
      </div>
    );
  }

  if (state === 'processing') {
    return (
      <div className="flex items-center gap-1.5 px-3 py-2 bg-zinc-800/60 border border-white/10 rounded-xl">
        <Volume2 size={14} className="text-purple-400 animate-pulse" />
        <span className="text-[10px] font-bold text-zinc-300">Transcribing...</span>
      </div>
    );
  }

  if (state === 'error') {
    return (
      <button
        type="button"
        onClick={start}
        title="Retry voice input"
        className="p-2.5 text-red-400 hover:text-red-300 hover:bg-red-950/30 rounded-2xl transition-colors"
      >
        <MicOff size={18} />
      </button>
    );
  }

  // Idle state
  return (
    <button
      type="button"
      onClick={start}
      title="Start voice input"
      className="p-2.5 text-zinc-400 hover:text-purple-300 hover:bg-purple-950/30 rounded-2xl transition-colors"
    >
      <Mic size={18} />
    </button>
  );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import { WorkspaceBrainData } from '@/lib/workspaceApi';

interface Props { brain: WorkspaceBrainData; }

const NODE_COLORS: Record<string, { bg: string; border: string; text: string; glow: string }> = {
  frontend:  { bg: 'rgba(59,130,246,0.15)',  border: '#3b82f6', text: '#93c5fd', glow: 'rgba(59,130,246,0.3)' },
  backend:   { bg: 'rgba(139,92,246,0.15)',  border: '#8b5cf6', text: '#c4b5fd', glow: 'rgba(139,92,246,0.3)' },
  database:  { bg: 'rgba(16,185,129,0.15)',  border: '#10b981', text: '#6ee7b7', glow: 'rgba(16,185,129,0.3)' },
  auth:      { bg: 'rgba(245,158,11,0.15)',  border: '#f59e0b', text: '#fcd34d', glow: 'rgba(245,158,11,0.3)' },
  service:   { bg: 'rgba(236,72,153,0.15)',  border: '#ec4899', text: '#f9a8d4', glow: 'rgba(236,72,153,0.3)' },
};

const LAYER_X: Record<string, number> = { frontend: 60, backend: 240, database: 420, auth: 600, service: 600 };
const LEGEND = [
  { type: 'frontend', label: 'Frontend' },
  { type: 'backend', label: 'Backend' },
  { type: 'database', label: 'Database' },
  { type: 'auth', label: 'Auth' },
  { type: 'service', label: 'Service' },
];

function getEdges(nodes: { id: string; type: string }[]) {
  const edges: { from: string; to: string }[] = [];
  const frontends = nodes.filter(n => n.type === 'frontend').map(n => n.id);
  const backends = nodes.filter(n => n.type === 'backend').map(n => n.id);
  const databases = nodes.filter(n => n.type === 'database').map(n => n.id);
  const auths = nodes.filter(n => n.type === 'auth').map(n => n.id);
  frontends.forEach(f => backends.forEach(b => edges.push({ from: f, to: b })));
  backends.forEach(b => databases.forEach(d => edges.push({ from: b, to: d })));
  backends.forEach(b => auths.forEach(a => edges.push({ from: b, to: a })));
  return edges;
}

export default function ArchitectureMap({ brain }: Props) {
  const [selectedNode, setSelectedNode] = useState<string | null>(null);
  const [hoveredNode, setHoveredNode] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const nodes = brain.architecture?.diagramNodes ?? [];
  const selected = nodes.find(n => n.id === selectedNode);
  const edges = getEdges(nodes);

  // Compute node positions
  const typeCount: Record<string, number> = {};
  const positions: Record<string, { x: number; y: number }> = {};
  nodes.forEach(node => {
    const type = node.type || 'service';
    const idx = typeCount[type] ?? 0;
    typeCount[type] = idx + 1;
    const baseY = 60 + idx * 90;
    const extraY = type === 'service' ? (typeCount['auth'] ?? 0) * 90 : 0;
    positions[node.id] = { x: LAYER_X[type] ?? 60, y: baseY + extraY };
  });

  const NODE_W = 140, NODE_H = 56;

  return (
    <div className="p-6 space-y-5">
      <div>
        <h2 className="text-xl font-bold text-white mb-1">Architecture Map</h2>
        <p className="text-zinc-500 text-sm">Interactive visualization of your project's layer structure.</p>
      </div>

      {nodes.length === 0 ? (
        // Fallback: structured list view
        <div className="space-y-4">
          <div className="bg-zinc-900/50 border border-blue-500/20 rounded-2xl p-4 text-center text-sm text-zinc-400 mb-2">
            No architecture nodes detected. Showing structural overview instead.
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {[
              { label: 'Entry Points', items: brain.architecture?.entryPoints ?? [], color: NODE_COLORS.frontend, icon: '🚪' },
              { label: 'API Routes', items: brain.architecture?.apiRoutes ?? [], color: NODE_COLORS.backend, icon: '🛣' },
              { label: 'UI Components', items: brain.architecture?.components ?? [], color: NODE_COLORS.frontend, icon: '🖼' },
              { label: 'DB Models', items: brain.architecture?.models ?? [], color: NODE_COLORS.database, icon: '📦' },
            ].map(section => (
              <div key={section.label} className="bg-zinc-900/60 rounded-xl border overflow-hidden" style={{ borderColor: section.color.border + '40' }}>
                <div className="px-4 py-3 border-b flex items-center gap-2" style={{ borderColor: section.color.border + '20', background: section.color.bg }}>
                  <span>{section.icon}</span>
                  <span className="text-sm font-semibold" style={{ color: section.color.text }}>{section.label}</span>
                  <span className="ml-auto text-xs px-1.5 py-0.5 rounded-full bg-white/10">{section.items.length}</span>
                </div>
                <div className="p-3 space-y-1 max-h-40 overflow-y-auto">
                  {section.items.length === 0 ? (
                    <p className="text-xs text-zinc-700">None detected</p>
                  ) : section.items.slice(0, 8).map(item => (
                    <div key={item} className="text-xs text-zinc-400 font-mono truncate py-0.5">{item}</div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="flex gap-4">
          {/* Graph Area */}
          <div className="flex-1 bg-zinc-900/60 border border-white/8 rounded-2xl overflow-hidden">
            <div
              ref={containerRef}
              className="relative overflow-x-auto"
              style={{ height: Math.max(400, Math.max(...Object.values(positions).map(p => p.y)) + 120) }}
            >
              {/* SVG edges */}
              <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ zIndex: 1 }}>
                <defs>
                  <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="10" refY="3.5" orient="auto">
                    <polygon points="0 0, 10 3.5, 0 7" fill="rgba(255,255,255,0.2)" />
                  </marker>
                  <marker id="arrowhead-hover" markerWidth="10" markerHeight="7" refX="10" refY="3.5" orient="auto">
                    <polygon points="0 0, 10 3.5, 0 7" fill="rgba(99,102,241,0.8)" />
                  </marker>
                </defs>
                {edges.map((edge, idx) => {
                  const from = positions[edge.from];
                  const to = positions[edge.to];
                  if (!from || !to) return null;
                  return (
                    <line
                      key={idx}
                      x1={from.x + NODE_W} y1={from.y + NODE_H / 2}
                      x2={to.x} y2={to.y + NODE_H / 2}
                      stroke="rgba(255,255,255,0.12)"
                      strokeWidth="1.5"
                      strokeDasharray="4 3"
                      markerEnd="url(#arrowhead)"
                    />
                  );
                })}
              </svg>

              {/* Node divs */}
              {nodes.map(node => {
                const pos = positions[node.id];
                if (!pos) return null;
                const colors = NODE_COLORS[node.type] ?? NODE_COLORS.service;
                const isSelected = selectedNode === node.id;
                const isHovered = hoveredNode === node.id;
                return (
                  <button
                    key={node.id}
                    onClick={() => setSelectedNode(isSelected ? null : node.id)}
                    onMouseEnter={() => setHoveredNode(node.id)}
                    onMouseLeave={() => setHoveredNode(null)}
                    className="absolute flex flex-col items-center justify-center rounded-xl text-center transition-all cursor-pointer"
                    style={{
                      left: pos.x, top: pos.y,
                      width: NODE_W, height: NODE_H,
                      background: colors.bg,
                      border: `1.5px solid ${isSelected ? colors.border : colors.border + '60'}`,
                      boxShadow: (isSelected || isHovered) ? `0 0 20px ${colors.glow}` : 'none',
                      transform: (isSelected || isHovered) ? 'scale(1.06)' : 'scale(1)',
                      zIndex: 2,
                    }}
                  >
                    <div className="text-lg">{node.type === 'frontend' ? '🖥' : node.type === 'backend' ? '⚙️' : node.type === 'database' ? '🗄' : node.type === 'auth' ? '🔐' : '🔌'}</div>
                    <div className="text-xs font-semibold leading-tight px-2 mt-0.5" style={{ color: colors.text }}>{node.label}</div>
                    <div className="text-[9px] mt-0.5" style={{ color: colors.text, opacity: 0.6 }}>{node.files.length} file{node.files.length !== 1 ? 's' : ''}</div>
                  </button>
                );
              })}
            </div>

            {/* Legend */}
            <div className="flex items-center gap-4 px-5 py-3 border-t border-white/8 flex-wrap">
              {LEGEND.map(item => {
                const colors = NODE_COLORS[item.type];
                return (
                  <div key={item.type} className="flex items-center gap-1.5 text-xs">
                    <span className="w-2.5 h-2.5 rounded-sm" style={{ background: colors.border, opacity: 0.7 }} />
                    <span className="text-zinc-500">{item.label}</span>
                  </div>
                );
              })}
              <div className="ml-auto text-xs text-zinc-600">{nodes.length} nodes · {edges.length} connections</div>
            </div>
          </div>

          {/* File Panel */}
          <div className={`transition-all duration-300 ${selected ? 'w-72 opacity-100' : 'w-0 opacity-0 overflow-hidden'}`}>
            {selected && (
              <div className="bg-zinc-900/80 border border-white/10 rounded-2xl p-4 h-full">
                <div className="flex items-center justify-between mb-3">
                  <div>
                    <h4 className="text-sm font-bold text-white">{selected.label}</h4>
                    <span className="text-[10px] px-2 py-0.5 rounded-full border mt-1 inline-block" style={{ borderColor: (NODE_COLORS[selected.type]?.border || '#fff') + '60', color: NODE_COLORS[selected.type]?.text }}>{selected.type}</span>
                  </div>
                  <button onClick={() => setSelectedNode(null)} className="text-zinc-600 hover:text-white text-lg">×</button>
                </div>
                <p className="text-xs text-zinc-600 mb-2">{selected.files.length} file{selected.files.length !== 1 ? 's' : ''}</p>
                <div className="space-y-1 max-h-72 overflow-y-auto">
                  {selected.files.map(fp => (
                    <div key={fp} className="flex items-center gap-2 text-xs py-1.5 px-2 rounded-lg hover:bg-white/5">
                      <span className="text-zinc-600">📄</span>
                      <code className="text-zinc-400 truncate">{fp}</code>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Stats Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {[
          { label: 'Entry Points', value: brain.architecture?.entryPoints?.length ?? 0, icon: '🚪' },
          { label: 'API Routes', value: brain.architecture?.apiRoutes?.length ?? 0, icon: '🛣' },
          { label: 'Components', value: brain.architecture?.components?.length ?? 0, icon: '🖼' },
          { label: 'DB Models', value: brain.architecture?.models?.length ?? 0, icon: '📦' },
        ].map(s => (
          <div key={s.label} className="bg-zinc-900/60 border border-white/8 rounded-xl p-4 flex items-center gap-3">
            <span className="text-xl">{s.icon}</span>
            <div>
              <div className="text-lg font-bold text-white">{s.value}</div>
              <div className="text-xs text-zinc-600">{s.label}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { getBuildPlan } from '@/lib/workspaceApi';

interface Props { workspaceId: string; }

interface PlanItem { feature: string; plan: string; createdAt: string; }

export default function BuildWithMeView({ workspaceId }: Props) {
  const [feature, setFeature] = useState('');
  const [loading, setLoading] = useState(false);
  const [plans, setPlans] = useState<PlanItem[]>([]);
  const [expanded, setExpanded] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!feature.trim()) return;
    setLoading(true);
    const { plan } = await getBuildPlan(workspaceId, feature.trim());
    const item: PlanItem = { feature: feature.trim(), plan, createdAt: new Date().toISOString() };
    setPlans(prev => [item, ...prev.slice(0, 2)]);
    setExpanded(item.createdAt);
    setFeature('');
    setLoading(false);
  };

  return (
    <div className="p-6 space-y-5">
      <div>
        <h2 className="text-xl font-bold text-white">Build With Me</h2>
        <p className="text-zinc-500 text-sm">Describe a feature and get a step-by-step implementation plan tailored to your codebase.</p>
      </div>

      <div className="bg-zinc-900/50 border border-white/8 rounded-2xl p-5 space-y-4">
        <label className="block text-sm font-medium text-zinc-300">What do you want to build?</label>
        <input
          value={feature}
          onChange={e => setFeature(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && !e.shiftKey && handleGenerate()}
          placeholder="e.g. Add user profile settings with avatar upload"
          className="w-full px-4 py-2.5 bg-zinc-900 border border-white/10 rounded-xl text-white placeholder-zinc-600 focus:outline-none focus:border-emerald-500/60 text-sm"
        />
        <button
          onClick={handleGenerate}
          disabled={loading || !feature.trim()}
          className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 hover:bg-emerald-500 disabled:bg-zinc-700 disabled:cursor-not-allowed rounded-xl text-white text-sm font-semibold transition-all"
        >
          {loading ? <><span className="animate-spin">⟳</span> Generating Plan...</> : '🛠 Generate Build Plan'}
        </button>
      </div>

      {plans.map((item, idx) => (
        <div key={item.createdAt} className="bg-zinc-900/50 border border-white/8 rounded-2xl overflow-hidden">
          <button
            onClick={() => setExpanded(expanded === item.createdAt ? null : item.createdAt)}
            className="w-full flex items-center justify-between px-5 py-4 hover:bg-white/3 transition-colors text-left"
          >
            <div>
              <h4 className="text-sm font-semibold text-white">{item.feature}</h4>
              <p className="text-xs text-zinc-600 mt-0.5">{new Date(item.createdAt).toLocaleString()}</p>
            </div>
            <span className="text-zinc-500">{expanded === item.createdAt ? '▲' : '▼'}</span>
          </button>
          {expanded === item.createdAt && (
            <div className="px-5 pb-5">
              <pre className="text-sm text-zinc-300 whitespace-pre-wrap leading-relaxed font-sans bg-zinc-950/50 rounded-xl p-4">{item.plan}</pre>
            </div>
          )}
        </div>
      ))}

      {plans.length === 0 && !loading && (
        <div className="text-center py-12 text-zinc-600">
          <div className="text-4xl mb-3">🛠</div>
          <p>Enter a feature above to generate your first build plan.</p>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { WorkspaceIssue, runCodeReview } from '@/lib/workspaceApi';

interface Props { workspaceId: string; initialIssues: WorkspaceIssue[]; }

const SEV_STYLES: Record<string, { bg: string; text: string; dot: string }> = {
  CRITICAL: { bg: 'bg-red-500/15 border-red-500/35 text-red-300', text: 'text-red-300', dot: 'bg-red-500' },
  HIGH:     { bg: 'bg-orange-500/15 border-orange-500/35 text-orange-300', text: 'text-orange-300', dot: 'bg-orange-500' },
  WARNING:  { bg: 'bg-yellow-500/15 border-yellow-500/35 text-yellow-300', text: 'text-yellow-300', dot: 'bg-yellow-400' },
  INFO:     { bg: 'bg-blue-500/15 border-blue-500/35 text-blue-300', text: 'text-blue-300', dot: 'bg-blue-400' },
};

function exportMarkdown(issues: WorkspaceIssue[], resolved: Set<string>) {
  const counts = { CRITICAL: 0, HIGH: 0, WARNING: 0, INFO: 0 };
  issues.forEach(i => { (counts as unknown)[i.severity]++; });
  const lines = [
    '# Code Review Report',
    '',
    `## Summary`,
    `${issues.length} issues found: ${counts.CRITICAL} critical, ${counts.HIGH} high, ${counts.WARNING} warnings, ${counts.INFO} info`,
    `${resolved.size} resolved`,
    '',
    '## Issues',
    '',
    ...issues.map(i => [
      `### ${i.title} (${i.severity})`,
      `**File:** \`${i.affectedFile}${i.lineRange ? ' · ' + i.lineRange : ''}\``,
      `**Category:** ${i.category}`,
      `**Status:** ${resolved.has(i.id) ? 'RESOLVED' : 'OPEN'}`,
      '',
      i.description,
      '',
      `> Why it matters: ${i.whyItMatters}`,
      '',
      `**Fix:** ${i.suggestedFix}`,
      '',
      '---',
      '',
    ].join('\n')),
  ].join('\n');
  const blob = new Blob([lines], { type: 'text/markdown' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'code-review.md'; a.click();
  URL.revokeObjectURL(url);
}

export default function CodeReviewView({ workspaceId, initialIssues }: Props) {
  const [issues, setIssues] = useState<WorkspaceIssue[]>(initialIssues ?? []);
  const [aiSummary, setAiSummary] = useState('');
  const [loading, setLoading] = useState(false);
  const [sevFilter, setSevFilter] = useState<string>('ALL');
  const [catFilter, setCatFilter] = useState<string>('ALL');
  const [resolved, setResolved] = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  const handleRunReview = async () => {
    setLoading(true);
    const result = await runCodeReview(workspaceId);
    setIssues(result.issues);
    setAiSummary(result.aiSummary);
    setLoading(false);
  };

  const toggleResolved = useCallback((id: string) => {
    setResolved(prev => { const next = new Set(prev); next.has(id) ? next.delete(id) : next.add(id); return next; });
  }, []);

  const toggleExpanded = useCallback((id: string) => {
    setExpanded(prev => { const next = new Set(prev); next.has(id) ? next.delete(id) : next.add(id); return next; });
  }, []);

  const categories = Array.from(new Set(issues.map(i => i.category)));
  const filtered = issues.filter(i =>
    (sevFilter === 'ALL' || i.severity === sevFilter) &&
    (catFilter === 'ALL' || i.category === catFilter)
  );
  const counts = { CRITICAL: 0, HIGH: 0, WARNING: 0, INFO: 0 };
  issues.forEach(i => { (counts as unknown)[i.severity]++; });
  const resolvedCount = issues.filter(i => resolved.has(i.id)).length;
  const resolvedPct = issues.length > 0 ? (resolvedCount / issues.length) * 100 : 0;

  return (
    <div className="p-6 space-y-5">
      {/* Progress Bar */}
      {issues.length > 0 && (
        <div>
          <div className="flex items-center justify-between text-xs text-zinc-500 mb-1.5">
            <span>{resolvedCount} of {issues.length} issues resolved</span>
            <span>{Math.round(resolvedPct)}%</span>
          </div>
          <div className="w-full h-1.5 bg-zinc-800 rounded-full overflow-hidden">
            <div className="h-full bg-emerald-500 rounded-full transition-all duration-500" style={{ width: `${resolvedPct}%` }} />
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h2 className="text-xl font-bold text-white">Code Review</h2>
          <p className="text-zinc-500 text-sm">Real static analysis from your uploaded project files.</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => exportMarkdown(issues, resolved)}
            disabled={issues.length === 0}
            className="flex items-center gap-2 px-4 py-2 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-40 border border-white/10 rounded-xl text-zinc-300 text-sm font-medium transition-all"
          >
            ↓ Export MD
          </button>
          <button
            onClick={handleRunReview}
            disabled={loading}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 disabled:bg-zinc-700 rounded-xl text-white text-sm font-semibold transition-all"
          >
            {loading ? <><span className="animate-spin inline-block">⟳</span> Scanning...</> : '🔍 Run Deep Review'}
          </button>
        </div>
      </div>

      {/* Severity Cards */}
      <div className="grid grid-cols-4 gap-3">
        {(['CRITICAL', 'HIGH', 'WARNING', 'INFO'] as const).map(sev => {
          const s = SEV_STYLES[sev];
          return (
            <button
              key={sev}
              onClick={() => setSevFilter(sevFilter === sev ? 'ALL' : sev)}
              className={`rounded-xl border p-4 text-center transition-all hover:scale-105 ${s.bg} ${sevFilter === sev ? 'ring-2 ring-white/20 shadow-lg' : ''}`}
            >
              <div className={`text-2xl font-black ${s.text}`}>{(counts as unknown)[sev]}</div>
              <div className="text-xs mt-1 opacity-80">{sev}</div>
            </button>
          );
        })}
      </div>

      {/* Filters */}
      <div className="space-y-2">
        <div className="flex gap-2 flex-wrap items-center">
          <span className="text-[10px] text-zinc-700 uppercase tracking-wider">Severity:</span>
          {(['ALL', 'CRITICAL', 'HIGH', 'WARNING', 'INFO'] as const).map(s => (
            <button key={s} onClick={() => setSevFilter(s)} className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${sevFilter === s ? 'bg-white/15 text-white' : 'text-zinc-500 hover:text-white'}`}>
              {s}
            </button>
          ))}
        </div>
        {categories.length > 0 && (
          <div className="flex gap-2 flex-wrap items-center">
            <span className="text-[10px] text-zinc-700 uppercase tracking-wider">Category:</span>
            <button onClick={() => setCatFilter('ALL')} className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${catFilter === 'ALL' ? 'bg-white/15 text-white' : 'text-zinc-500 hover:text-white'}`}>ALL</button>
            {categories.map(c => (
              <button key={c} onClick={() => setCatFilter(c)} className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${catFilter === c ? 'bg-white/15 text-white' : 'text-zinc-500 hover:text-white'}`}>{c}</button>
            ))}
          </div>
        )}
      </div>

      {/* AI Summary */}
      {aiSummary && (
        <div className="bg-blue-600/10 border border-blue-500/25 rounded-xl p-4">
          <h4 className="text-sm font-semibold text-blue-300 mb-2">🤖 AI Review Summary</h4>
          <pre className="text-xs text-zinc-300 whitespace-pre-wrap leading-relaxed font-sans">{aiSummary}</pre>
        </div>
      )}

      {/* Issues List */}
      {filtered.length === 0 ? (
        <div className="text-center py-16">
          <div className="text-5xl mb-4">{issues.length === 0 ? '✅' : '🔍'}</div>
          <p className="text-zinc-500">{issues.length === 0 ? 'No issues detected — run a review to scan your project.' : 'No issues match selected filters.'}</p>
        </div>
      ) : (
        <div className="space-y-2">
          {filtered.map((issue, idx) => {
            const s = SEV_STYLES[issue.severity] ?? SEV_STYLES.INFO;
            const isExpanded = expanded.has(issue.id);
            const isResolved = resolved.has(issue.id);
            return (
              <div
                key={issue.id}
                className={`bg-zinc-900/70 border border-white/8 rounded-xl overflow-hidden transition-all ${isResolved ? 'opacity-50' : ''}`}
                style={{ animationDelay: `${idx * 40}ms` }}
              >
                {/* Collapsed Header */}
                <div className="flex items-center gap-3 px-4 py-3">
                  <span className={`w-2 h-2 rounded-full flex-shrink-0 ${s.dot}`} />
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold border ${s.bg}`}>{issue.severity}</span>
                      <span className="text-[10px] text-zinc-600 border border-white/10 rounded px-2 py-0.5">{issue.category}</span>
                      <code className="text-[10px] text-blue-400 font-mono">{issue.affectedFile}{issue.lineRange ? ` · ${issue.lineRange}` : ''}</code>
                    </div>
                    <h4 className={`text-sm font-semibold mt-1.5 ${isResolved ? 'line-through text-zinc-600' : 'text-white'}`}>{issue.title}</h4>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <button
                      onClick={() => toggleResolved(issue.id)}
                      className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all border ${isResolved ? 'bg-emerald-600/20 text-emerald-400 border-emerald-600/30' : 'bg-zinc-800 text-zinc-400 hover:text-white border-white/10'}`}
                    >
                      {isResolved ? '✓ Resolved' : 'Resolve'}
                    </button>
                    <button
                      onClick={() => toggleExpanded(issue.id)}
                      className={`p-1.5 rounded-lg text-zinc-500 hover:text-white hover:bg-white/8 transition-all ${isExpanded ? 'rotate-90' : ''}`}
                      style={{ transition: 'transform 0.2s ease' }}
                    >
                      ▶
                    </button>
                  </div>
                </div>

                {/* Expanded Details */}
                {isExpanded && (
                  <div className="border-t border-white/6 px-4 py-4 space-y-3 bg-zinc-950/30">
                    <p className="text-sm text-zinc-300">{issue.description}</p>
                    <p className="text-xs text-zinc-500 italic">{issue.whyItMatters}</p>
                    <div className="bg-emerald-900/20 border border-emerald-700/25 rounded-xl px-4 py-3">
                      <span className="text-xs text-emerald-400 font-semibold">💡 Suggested Fix: </span>
                      <span className="text-xs text-zinc-300">{issue.suggestedFix}</span>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

