                <p className="text-zinc-400 leading-relaxed">{q}</p>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { WorkspaceMemory, addMemory, deleteMemory } from '@/lib/workspaceApi';

interface Props { workspaceId: string; initialMemories: WorkspaceMemory[]; }

const TYPE_META: Record<string, { icon: string; bg: string; border: string; text: string; dot: string }> = {
  GOAL:           { icon: '🎯', bg: 'bg-emerald-500/10', border: 'border-emerald-500/25', text: 'text-emerald-300', dot: 'bg-emerald-400' },
  STACK_DECISION: { icon: '🛠', bg: 'bg-blue-500/10',    border: 'border-blue-500/25',    text: 'text-blue-300',    dot: 'bg-blue-400' },
  ARCHITECTURE:   { icon: '🗺️', bg: 'bg-amber-500/10',   border: 'border-amber-500/25',   text: 'text-amber-300',   dot: 'bg-amber-400' },
  NOTE:           { icon: '📝', bg: 'bg-zinc-700/30',    border: 'border-white/10',       text: 'text-zinc-400',    dot: 'bg-zinc-500' },
};
const TYPES = ['GOAL', 'STACK_DECISION', 'ARCHITECTURE', 'NOTE'] as const;

export default function ProjectMemoryView({ workspaceId, initialMemories }: Props) {
  const [memories, setMemories] = useState<WorkspaceMemory[]>(initialMemories ?? []);
  const [filterType, setFilterType] = useState<string>('ALL');
  const [search, setSearch] = useState('');
  const [showAdd, setShowAdd] = useState(false);
  const [newType, setNewType] = useState<typeof TYPES[number]>('NOTE');
  const [newContent, setNewContent] = useState('');
  const [adding, setAdding] = useState(false);
  const [pinned, setPinned] = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  const filteredBase = memories
    .filter(m => filterType === 'ALL' || m.type === filterType)
    .filter(m => !search || m.content.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  const pinnedMems = filteredBase.filter(m => pinned.has(m.id));
  const unpinnedMems = filteredBase.filter(m => !pinned.has(m.id));
  const allVisible = [...pinnedMems, ...unpinnedMems];

  const handleAdd = useCallback(async () => {
    if (!newContent.trim()) return;
    setAdding(true);
    const mem = await addMemory(workspaceId, newType, newContent.trim());
    if (mem) setMemories(prev => [mem, ...prev]);
    setNewContent(''); setShowAdd(false); setAdding(false);
  }, [workspaceId, newType, newContent]);

  const handleDelete = useCallback(async (id: string) => {
    await deleteMemory(workspaceId, id);
    setMemories(prev => prev.filter(m => m.id !== id));
    setConfirmDelete(null);
  }, [workspaceId]);

  const togglePin = (id: string) => setPinned(prev => { const s = new Set(prev); s.has(id) ? s.delete(id) : s.add(id); return s; });
  const toggleExpand = (id: string) => setExpanded(prev => { const s = new Set(prev); s.has(id) ? s.delete(id) : s.add(id); return s; });

  return (
    <div className="p-6 space-y-5 h-full flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3 flex-shrink-0">
        <div>
          <h2 className="text-xl font-bold text-white">Project Memory</h2>
          <p className="text-zinc-500 text-sm">Persistent store for goals, stack decisions, and architectural choices.</p>
        </div>
        <button
          onClick={() => setShowAdd(!showAdd)}
          className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-500 hover:to-violet-500 rounded-xl text-white text-sm font-semibold transition-all shadow-lg shadow-blue-600/20"
        >
          {showAdd ? '× Cancel' : '+ Add Memory'}
        </button>
      </div>

      {/* Add Form */}
      {showAdd && (
        <div className="bg-zinc-900/60 border border-blue-500/20 rounded-2xl p-5 space-y-3 flex-shrink-0">
          <div className="flex gap-2 flex-wrap">
            {TYPES.map(t => {
              const meta = TYPE_META[t];
              return (
                <button
                  key={t}
                  onClick={() => setNewType(t)}
                  className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl border text-xs font-semibold transition-all ${newType === t ? `${meta.bg} ${meta.border} ${meta.text}` : 'bg-zinc-800 border-white/10 text-zinc-500'}`}
                >
                  <span>{meta.icon}</span>{t.replace('_', ' ')}
                </button>
              );
            })}
          </div>
          <textarea
            value={newContent}
            onChange={e => setNewContent(e.target.value)}
            placeholder="e.g. We chose PostgreSQL because we need ACID compliance for financial transactions..."
            rows={3}
            className="w-full px-4 py-3 bg-zinc-950/80 border border-white/10 rounded-xl text-white text-sm focus:outline-none focus:border-blue-500/50 resize-none"
          />
          <button
            onClick={handleAdd}
            disabled={adding || !newContent.trim()}
            className="px-5 py-2 bg-blue-600 hover:bg-blue-500 disabled:bg-zinc-700 disabled:cursor-not-allowed rounded-xl text-white text-sm font-semibold transition-all"
          >
            {adding ? 'Saving...' : '+ Save Memory'}
          </button>
        </div>
      )}

      {/* Search + Filters */}
      <div className="space-y-2 flex-shrink-0">
        <div className="relative">
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-600 text-sm">🔍</span>
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search memories..."
            className="w-full pl-9 pr-4 py-2.5 bg-zinc-900/60 border border-white/10 rounded-xl text-white text-sm placeholder-zinc-600 focus:outline-none focus:border-blue-500/40"
          />
          {search && (
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-zinc-600">
              {allVisible.length} of {memories.length}
            </span>
          )}
        </div>
        <div className="flex gap-2 flex-wrap">
          <button onClick={() => setFilterType('ALL')} className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${filterType === 'ALL' ? 'bg-white/15 text-white' : 'text-zinc-500 hover:text-white'}`}>
            All ({memories.length})
          </button>
          {TYPES.map(t => (
            <button key={t} onClick={() => setFilterType(t)} className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${filterType === t ? 'bg-white/15 text-white' : 'text-zinc-500 hover:text-white'}`}>
              {TYPE_META[t].icon} {t.replace('_', ' ')} ({memories.filter(m => m.type === t).length})
            </button>
          ))}
        </div>
      </div>

      {/* Memory Timeline */}
      <div className="flex-1 overflow-y-auto">
        {allVisible.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-48 gap-3">
            <div className="text-4xl">🧠</div>
            <p className="text-zinc-600 text-sm">No memories yet. Start capturing decisions.</p>
          </div>
        ) : (
          <div className="relative pl-8">
            {/* Timeline line */}
            <div className="absolute left-3 top-0 bottom-0 w-px bg-gradient-to-b from-blue-500/30 via-white/8 to-transparent" />

            <div className="space-y-4">
              {allVisible.map((mem, idx) => {
                const meta = TYPE_META[mem.type] ?? TYPE_META.NOTE;
                const isPinned = pinned.has(mem.id);
                const isExpanded = expanded.has(mem.id);
                const isLong = mem.content.length > 150;
                const isConfirmingDelete = confirmDelete === mem.id;
                return (
                  <div key={mem.id} className="relative">
                    {/* Timeline dot */}
                    <div className={`absolute -left-5 w-3 h-3 rounded-full border-2 border-zinc-950 mt-4 ${meta.dot}`} />

                    <div className={`rounded-xl border p-4 transition-all hover:border-opacity-60 ${isPinned ? 'border-amber-400/40 bg-amber-500/5' : 'border-white/8 bg-zinc-900/60'}`}>
                      {/* Card Header */}
                      <div className="flex items-start justify-between gap-3 mb-2">
                        <div className="flex items-center gap-2 flex-wrap">
                          {isPinned && <span className="text-xs text-amber-400">📌</span>}
                          <span className={`px-2 py-0.5 text-[10px] font-bold rounded border ${meta.bg} ${meta.border} ${meta.text}`}>
                            {meta.icon} {mem.type.replace('_', ' ')}
                          </span>
                          <span className="text-xs text-zinc-600">{mem.source}</span>
                        </div>
                        <div className="flex items-center gap-1 flex-shrink-0">
                          <button
                            onClick={() => togglePin(mem.id)}
                            className={`p-1.5 rounded-lg text-xs transition-all ${isPinned ? 'text-amber-400 bg-amber-500/10' : 'text-zinc-600 hover:text-amber-400 hover:bg-amber-500/10'}`}
                            title={isPinned ? 'Unpin' : 'Pin'}
                          >
                            📌
                          </button>
                          {isConfirmingDelete ? (
                            <div className="flex items-center gap-1">
                              <button onClick={() => handleDelete(mem.id)} className="px-2 py-1 text-[10px] text-red-400 hover:bg-red-500/15 rounded-lg transition-colors">Yes</button>
                              <button onClick={() => setConfirmDelete(null)} className="px-2 py-1 text-[10px] text-zinc-500 hover:bg-white/8 rounded-lg transition-colors">No</button>
                            </div>
                          ) : (
                            <button onClick={() => setConfirmDelete(mem.id)} className="p-1.5 rounded-lg text-zinc-600 hover:text-red-400 hover:bg-red-500/10 transition-all" title="Delete">
                              🗑
                            </button>
                          )}
                        </div>
                      </div>

                      {/* Content */}
                      <p className="text-sm text-zinc-300 leading-relaxed">
                        {isLong && !isExpanded ? mem.content.slice(0, 150) + '...' : mem.content}
                      </p>
                      {isLong && (
                        <button onClick={() => toggleExpand(mem.id)} className="text-xs text-blue-400 hover:text-blue-300 mt-1 transition-colors">
                          {isExpanded ? '▲ Show less' : '▼ Show more'}
                        </button>
                      )}

                      <p className="text-[10px] text-zinc-700 mt-2">{new Date(mem.createdAt).toLocaleString()}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useCallback, useRef } from 'react';
import { WorkspaceTask, addTask, updateTaskStatus } from '@/lib/workspaceApi';

interface Props { workspaceId: string; initialTasks: WorkspaceTask[]; }

const COLUMNS: { status: WorkspaceTask['status']; label: string; color: string; headerBg: string; dot: string }[] = [
  { status: 'PENDING',     label: 'Pending',     color: 'border-zinc-700/50',   headerBg: 'from-zinc-800/60 to-zinc-900/40',  dot: 'bg-zinc-500' },
  { status: 'IN_PROGRESS', label: 'In Progress', color: 'border-blue-500/30',   headerBg: 'from-blue-900/30 to-blue-950/20',  dot: 'bg-blue-400' },
  { status: 'COMPLETED',   label: 'Completed',   color: 'border-emerald-500/30',headerBg: 'from-emerald-900/25 to-emerald-950/15', dot: 'bg-emerald-400' },
];
const PRIORITY_BORDER: Record<string, string> = { HIGH: 'border-l-red-500', MEDIUM: 'border-l-yellow-500', LOW: 'border-l-zinc-600' };
const PRIORITY_BADGE: Record<string, string> = { HIGH: 'bg-red-500/15 border-red-500/30 text-red-300', MEDIUM: 'bg-yellow-500/15 border-yellow-500/30 text-yellow-300', LOW: 'bg-zinc-700/50 border-white/10 text-zinc-500' };

export default function TaskSystemView({ workspaceId, initialTasks }: Props) {
  const [tasks, setTasks] = useState<WorkspaceTask[]>(initialTasks ?? []);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [dragOverCol, setDragOverCol] = useState<string | null>(null);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState('');
  const [newTitle, setNewTitle] = useState('');
  const [newDesc, setNewDesc] = useState('');
  const [newPriority, setNewPriority] = useState<'HIGH' | 'MEDIUM' | 'LOW'>('MEDIUM');
  const [adding, setAdding] = useState(false);

  const total = tasks.length;
  const completedCount = tasks.filter(t => t.status === 'COMPLETED').length;
  const progressPct = total > 0 ? (completedCount / total) * 100 : 0;

  const handleDragStart = (e: React.DragEvent, taskId: string) => {
    e.dataTransfer.setData('taskId', taskId);
    setDraggingId(taskId);
  };
  const handleDragEnd = () => { setDraggingId(null); setDragOverCol(null); };
  const handleDragOver = (e: React.DragEvent, status: string) => {
    e.preventDefault();
    setDragOverCol(status);
  };
  const handleDrop = useCallback(async (e: React.DragEvent, newStatus: WorkspaceTask['status']) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    setDraggingId(null); setDragOverCol(null);
    if (!taskId) return;
    const task = tasks.find(t => t.id === taskId);
    if (!task || task.status === newStatus) return;
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: newStatus } : t));
    await updateTaskStatus(workspaceId, taskId, newStatus);
  }, [tasks, workspaceId]);

  const handleAddTask = async () => {
    if (!newTitle.trim()) return;
    setAdding(true);
    const task = await addTask(workspaceId, { title: newTitle, description: newDesc, priority: newPriority, source: 'USER' });
    if (task) setTasks(prev => [...prev, task]);
    setNewTitle(''); setNewDesc(''); setNewPriority('MEDIUM'); setShowAddModal(false); setAdding(false);
  };

  const startEdit = (task: WorkspaceTask) => { setEditingId(task.id); setEditTitle(task.title); };
  const saveEdit = (taskId: string) => {
    if (editTitle.trim()) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, title: editTitle.trim() } : t));
    setEditingId(null);
  };

  return (
    <div className="p-6 space-y-5 h-full flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3 flex-shrink-0">
        <div>
          <h2 className="text-xl font-bold text-white">Task Board</h2>
          <p className="text-zinc-500 text-sm">{total} tasks · {completedCount} completed · {total - completedCount} remaining</p>
        </div>
        <button
          onClick={() => setShowAddModal(true)}
          className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-blue-600 to-violet-600 hover:from-blue-500 hover:to-violet-500 rounded-xl text-white text-sm font-semibold transition-all shadow-lg shadow-blue-600/20"
        >
          + Add Task
        </button>
      </div>

      {/* Progress */}
      {total > 0 && (
        <div className="flex-shrink-0">
          <div className="flex justify-between text-xs text-zinc-600 mb-1.5">
            <span>Progress</span>
            <span>{completedCount}/{total} tasks done</span>
          </div>
          <div className="h-1.5 bg-zinc-800 rounded-full overflow-hidden">
            <div className="h-full bg-gradient-to-r from-emerald-500 to-teal-500 rounded-full transition-all duration-700" style={{ width: `${progressPct}%` }} />
          </div>
        </div>
      )}

      {/* Kanban Columns */}
      <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-4 min-h-0">
        {COLUMNS.map(col => {
          const colTasks = tasks.filter(t => t.status === col.status);
          const isDragTarget = dragOverCol === col.status;
          return (
            <div
              key={col.status}
              onDragOver={e => handleDragOver(e, col.status)}
              onDrop={e => handleDrop(e, col.status)}
              onDragLeave={() => setDragOverCol(null)}
              className={`flex flex-col rounded-2xl border transition-all ${col.color} ${isDragTarget ? 'border-opacity-100 scale-[1.01] shadow-lg' : 'border-opacity-40'}`}
              style={{ background: 'rgba(9,9,15,0.5)', minHeight: 200 }}
            >
              {/* Column Header */}
              <div className={`flex items-center justify-between px-4 py-3 border-b ${col.color} rounded-t-2xl bg-gradient-to-r ${col.headerBg}`}>
                <div className="flex items-center gap-2">
                  <span className={`w-2 h-2 rounded-full ${col.dot}`} />
                  <span className="text-sm font-semibold text-white">{col.label}</span>
                </div>
                <span className="text-xs px-2 py-0.5 rounded-full bg-white/10 text-zinc-400">{colTasks.length}</span>
              </div>

              {/* Tasks */}
              <div className="flex-1 p-3 space-y-2 overflow-y-auto">
                {colTasks.length === 0 ? (
                  <div className={`flex items-center justify-center h-20 rounded-xl border border-dashed ${isDragTarget ? 'border-white/25 bg-white/5' : 'border-white/10'} transition-all`}>
                    <p className="text-xs text-zinc-700">Drop tasks here</p>
                  </div>
                ) : colTasks.map(task => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={e => handleDragStart(e, task.id)}
                    onDragEnd={handleDragEnd}
                    className={`group bg-zinc-900/80 border border-white/8 border-l-4 ${PRIORITY_BORDER[task.priority]} rounded-xl p-3 cursor-grab active:cursor-grabbing transition-all hover:border-white/15 hover:shadow-lg ${draggingId === task.id ? 'opacity-50 scale-95' : ''}`}
                  >
                    <div className="flex items-start gap-2">
                      <span className="text-zinc-700 mt-0.5 flex-shrink-0 cursor-grab">⠿</span>
                      <div className="flex-1 min-w-0">
                        <div className="flex gap-1.5 mb-1.5 flex-wrap">
                          <span className={`px-1.5 py-0.5 text-[9px] font-bold rounded border ${PRIORITY_BADGE[task.priority]}`}>{task.priority}</span>
                          <span className={`px-1.5 py-0.5 text-[9px] rounded border ${task.source === 'AI_AUDIT' ? 'bg-purple-600/15 border-purple-500/25 text-purple-400' : 'bg-blue-600/15 border-blue-500/25 text-blue-400'}`}>
                            {task.source === 'AI_AUDIT' ? '🤖' : '👤'}
                          </span>
                        </div>
                        {editingId === task.id ? (
                          <input
                            autoFocus
                            value={editTitle}
                            onChange={e => setEditTitle(e.target.value)}
                            onKeyDown={e => { if (e.key === 'Enter') saveEdit(task.id); if (e.key === 'Escape') setEditingId(null); }}
                            onBlur={() => saveEdit(task.id)}
                            className="w-full bg-zinc-800 border border-blue-500/40 rounded-lg px-2 py-1 text-sm text-white focus:outline-none"
                          />
                        ) : (
                          <h4
                            onDoubleClick={() => startEdit(task)}
                            className={`text-sm font-medium leading-snug cursor-text ${col.status === 'COMPLETED' ? 'line-through text-zinc-600' : 'text-white'}`}
                            title="Double-click to edit"
                          >
                            {task.title}
                          </h4>
                        )}
                        {task.description && <p className="text-xs text-zinc-600 mt-1 leading-relaxed">{task.description}</p>}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {/* Add Task Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowAddModal(false)} />
          <div className="relative z-10 w-full max-w-md bg-zinc-900 border border-white/15 rounded-2xl p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-bold text-white">Add New Task</h3>
              <button onClick={() => setShowAddModal(false)} className="text-zinc-500 hover:text-white text-xl">×</button>
            </div>
            <div className="space-y-3">
              <input
                value={newTitle}
                onChange={e => setNewTitle(e.target.value)}
                placeholder="Task title..."
                className="w-full px-4 py-2.5 bg-zinc-800 border border-white/10 rounded-xl text-white text-sm focus:outline-none focus:border-blue-500/50"
              />
              <input
                value={newDesc}
                onChange={e => setNewDesc(e.target.value)}
                placeholder="Description (optional)..."
                className="w-full px-4 py-2.5 bg-zinc-800 border border-white/10 rounded-xl text-white text-sm focus:outline-none focus:border-blue-500/50"
              />
              <div className="flex gap-2">
                {(['HIGH', 'MEDIUM', 'LOW'] as const).map(p => (
                  <button
                    key={p}
                    onClick={() => setNewPriority(p)}
                    className={`flex-1 py-2 rounded-xl text-xs font-semibold border transition-all ${newPriority === p ? PRIORITY_BADGE[p] : 'bg-zinc-800 border-white/10 text-zinc-500'}`}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setShowAddModal(false)} className="flex-1 py-2.5 rounded-xl bg-zinc-800 border border-white/10 text-zinc-400 text-sm hover:text-white transition-colors">Cancel</button>
              <button
                onClick={handleAddTask}
                disabled={!newTitle.trim() || adding}
                className="flex-1 py-2.5 rounded-xl bg-gradient-to-r from-blue-600 to-violet-600 text-white text-sm font-semibold disabled:opacity-50 disabled:cursor-not-allowed transition-all"
              >
                {adding ? 'Adding...' : 'Create Task'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

